<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import PageHeader from "@/components/PageHeader.vue";
import { ApiError } from "@/services/http";
import { useAuthSession } from "@/composables/useAuthSession";
import { createAsignacion, createTarjeta, getAccessOptions, getTarjetaOptions, listAsignaciones, listTarjetas, listTarjetasDisponibles, renewAsignacion, replaceAsignacion, returnAsignacion, type Asignacion, type PerfilAcceso, type Tarjeta, type TarjetaDisponible, type TarjetaOptions } from "@/services/tarjetas";

const session = useAuthSession();
const cards = ref<Tarjeta[]>([]); const available = ref<TarjetaDisponible[]>([]); const options = ref<TarjetaOptions>({ estadosTarjeta: [], tiposTarjeta: [], tiposVigencia: [], estadosAsignacion: [], beneficiarios: [], solicitudes: [] }); const profiles = ref<PerfilAcceso[]>([]);
const search = ref(""); const estado = ref<"all"|"active"|"inactive">("all"); const page = ref(1); const pagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 });
const loading = ref(false); const saving = ref(false); const error = ref(""); const success = ref(""); const showCardForm = ref(false); const detail = ref<Tarjeta|null>(null); const history = ref<Asignacion[]>([]); const action = ref<"assign"|"return"|"renew"|"replace"|"history"|null>(null);
const cardForm = ref({ codigoTarjeta: "", codigoExterno: "", numeroSerie: "", idEstadoTarjeta: 0, idTipoTarjeta: null as number|null, fechaAdquisicion: "", fechaAlta: new Date().toISOString().slice(0, 10), fechaBaja: "", motivoBaja: "", requiereRevision: false, observacionTarjeta: "" });
const assignmentForm = ref({ idBeneficiario: "", idSolicitud: "", idTarjetaNueva: "", idTipoVigencia: 0, idEstadoAsignacion: 0, fechaInicioVigencia: new Date().toISOString().slice(0, 10), fechaFinVigencia: "", idPerfilAcceso: "", motivo: "" });
const message = (e: unknown) => e instanceof ApiError ? e.message : "Ocurrió un error inesperado";
const can = (permission: string) => session.user.value?.permissions.includes(permission) ?? false;
const cardFormValid = computed(() => Boolean(cardForm.value.codigoTarjeta && cardForm.value.idEstadoTarjeta > 0 && cardForm.value.fechaAlta));
const actionValid = computed(() => Boolean(detail.value && assignmentForm.value.idBeneficiario && assignmentForm.value.idSolicitud && assignmentForm.value.idTipoVigencia > 0 && assignmentForm.value.idEstadoAsignacion > 0 && assignmentForm.value.fechaInicioVigencia && (!assignmentForm.value.fechaFinVigencia || assignmentForm.value.fechaFinVigencia >= assignmentForm.value.fechaInicioVigencia)));
const actionConfirmable = computed(() => action.value === "assign" ? actionValid.value : Boolean(assignmentForm.value.motivo && assignmentForm.value.idEstadoAsignacion > 0 && (action.value !== "replace" || assignmentForm.value.idTarjetaNueva) && (action.value !== "renew" || (!assignmentForm.value.fechaFinVigencia || assignmentForm.value.fechaFinVigencia >= assignmentForm.value.fechaInicioVigencia))));
const filteredRequests = computed(() => options.value.solicitudes.filter(item => !assignmentForm.value.idBeneficiario || String(item.idBeneficiario) === assignmentForm.value.idBeneficiario));

async function load() { loading.value = true; error.value = ""; try { const result = await listTarjetas(search.value, page.value, estado.value); cards.value = result.items; pagination.value = result.pagination; } catch (e) { error.value = message(e); } finally { loading.value = false; } }
async function loadOptions() { try { options.value = await getTarjetaOptions(); profiles.value = (await getAccessOptions()).perfilesAcceso; } catch (e) { error.value = message(e); } }
async function loadAvailable() { available.value = await listTarjetasDisponibles(); }
function resetCardForm() { cardForm.value = { codigoTarjeta: "", codigoExterno: "", numeroSerie: "", idEstadoTarjeta: 0, idTipoTarjeta: null, fechaAdquisicion: "", fechaAlta: new Date().toISOString().slice(0, 10), fechaBaja: "", motivoBaja: "", requiereRevision: false, observacionTarjeta: "" }; showCardForm.value = true; }
function date(value: string) { return value ? new Date(`${value}T00:00:00`) : null; }
async function saveCard() { if (!cardFormValid.value) return; saving.value = true; error.value = ""; try { await createTarjeta({ ...cardForm.value, codigoExterno: cardForm.value.codigoExterno || null, numeroSerie: cardForm.value.numeroSerie || null, fechaAdquisicion: date(cardForm.value.fechaAdquisicion), fechaAlta: date(cardForm.value.fechaAlta)!, fechaBaja: date(cardForm.value.fechaBaja), motivoBaja: cardForm.value.motivoBaja || null, observacionTarjeta: cardForm.value.observacionTarjeta || null, assignment: null }); showCardForm.value = false; success.value = "Tarjeta registrada correctamente."; await load(); } catch (e) { error.value = message(e); } finally { saving.value = false; } }
async function openDetail(card: Tarjeta) { detail.value = card; action.value = null; error.value = ""; try { history.value = await listAsignaciones(true); history.value = history.value.filter(item => String(item.idTarjeta) === String(card.idTarjeta)); } catch (e) { error.value = message(e); } }
function beginAction(next: "assign"|"return"|"renew"|"replace") { action.value = next; assignmentForm.value = { idBeneficiario: String(detail.value?.idBeneficiario ?? ""), idSolicitud: String(detail.value?.idSolicitud ?? ""), idTarjetaNueva: "", idTipoVigencia: 0, idEstadoAsignacion: detail.value?.idEstadoAsignacion ?? 0, fechaInicioVigencia: detail.value?.fechaInicioVigencia?.slice(0, 10) ?? new Date().toISOString().slice(0, 10), fechaFinVigencia: detail.value?.fechaFinVigencia?.slice(0, 10) ?? "", idPerfilAcceso: "", motivo: "" }; }
async function saveAction() { if (!detail.value || !action.value || action.value === "history") return; saving.value = true; error.value = ""; try { const id = detail.value.idAsignacion!; if (action.value === "assign") { if (!actionValid.value) return; await createAsignacion({ idTarjeta: String(detail.value.idTarjeta), idBeneficiario: assignmentForm.value.idBeneficiario, idSolicitud: assignmentForm.value.idSolicitud, idTipoVigencia: assignmentForm.value.idTipoVigencia, idEstadoAsignacion: assignmentForm.value.idEstadoAsignacion, fechaAsignacion: new Date().toISOString(), fechaInicioVigencia: new Date(`${assignmentForm.value.fechaInicioVigencia}T00:00:00`).toISOString(), fechaFinVigencia: date(assignmentForm.value.fechaFinVigencia)?.toISOString() ?? null, idPerfilAcceso: assignmentForm.value.idPerfilAcceso ? Number(assignmentForm.value.idPerfilAcceso) : null, observacionEntrega: assignmentForm.value.motivo || null }); } else if (action.value === "return") { await returnAsignacion(id, { idEstadoAsignacionNuevo: assignmentForm.value.idEstadoAsignacion, motivoCambio: assignmentForm.value.motivo, usuario: "backoffice" }); } else if (action.value === "renew") { await renewAsignacion(id, { fechaInicioVigencia: new Date(`${assignmentForm.value.fechaInicioVigencia}T00:00:00`).toISOString(), fechaFinVigencia: date(assignmentForm.value.fechaFinVigencia)?.toISOString() ?? null, motivoCambio: assignmentForm.value.motivo, usuario: "backoffice" }); } else { await replaceAsignacion(id, { idTarjetaNueva: assignmentForm.value.idTarjetaNueva, idEstadoAsignacion: assignmentForm.value.idEstadoAsignacion, motivoReemplazo: assignmentForm.value.motivo, fechaFinVigencia: date(assignmentForm.value.fechaFinVigencia)?.toISOString() ?? null, usuario: "backoffice" }); } success.value = "Operación realizada correctamente."; action.value = null; await load(); const refreshed = cards.value.find(card => String(card.idTarjeta) === String(detail.value?.idTarjeta)); if (refreshed) await openDetail(refreshed); } catch (e) { error.value = message(e); } finally { saving.value = false; } }
function changePage(next: number) { page.value = next; void load(); }
onMounted(() => { void Promise.all([load(), loadOptions(), loadAvailable(), session.restore()]); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Operación', to: '/' }, { label: 'Tarjetas' }]" />
  <PageHeader eyebrow="Operación" title="Tarjetas" description="Registro lógico de tarjetas SIGA y gestión de sus asignaciones."  :action-label="can('TARJETAS_ASIGNAR') ? 'Nueva tarjeta' : undefined" @action="resetCardForm" />
  <div v-if="success" class="bo-notice bo-notice-success">{{ success }}</div><div v-if="error" class="bo-state bo-state-error">{{ error }} <button class="bo-link" @click="load">Reintentar</button></div>
  <section class="bo-card"><form class="bo-toolbar" @submit.prevent="page = 1; load()"><input v-model="search" placeholder="Buscar por código, serie o beneficiario..." aria-label="Buscar tarjetas" /><select v-model="estado" aria-label="Filtrar estado"><option value="all">Todos los estados</option><option value="active">Activas</option><option value="inactive">Inactivas</option></select><button class="bo-btn bo-btn-primary">Filtrar</button></form><div v-if="loading" class="bo-state">Cargando tarjetas...</div><div v-else-if="!cards.length" class="bo-state"><strong>No hay tarjetas registradas.</strong><span>La pantalla no crea inventario físico; registra únicamente la entidad lógica en SIGA.</span></div><div v-else class="bo-table-wrap"><table><thead><tr><th>Tarjeta</th><th>Estado</th><th>Asignación</th><th>Beneficiario</th><th>Perfil</th><th>Vigencia</th><th>Acciones</th></tr></thead><tbody><tr v-for="card in cards" :key="String(card.idTarjeta)"><td><strong>{{ card.codigoTarjeta }}</strong><small class="tarjeta-secondary">{{ card.numeroSerie ?? card.codigoExterno ?? "Sin referencia adicional" }}</small></td><td>{{ card.nombreEstadoTarjeta }}</td><td><span class="status-badge" :class="{ 'status-badge--inactive': !card.idAsignacion }">{{ card.idAsignacion ? (card.nombreEstadoAsignacion ?? "Asignada") : "Disponible" }}</span></td><td>{{ card.nombreBeneficiario ?? "—" }}</td><td>{{ card.perfilesAcceso ?? "—" }}</td><td>{{ card.idAsignacion ? `${card.fechaInicioVigencia?.slice(0, 10)} — ${card.fechaFinVigencia?.slice(0, 10) ?? "Sin vencimiento"}` : "—" }}</td><td><button class="bo-action" @click="openDetail(card)">Gestionar</button></td></tr></tbody></table></div><footer v-if="!loading" class="bo-pagination"><span>{{ pagination.total }} tarjetas · Página {{ pagination.page }} de {{ Math.max(pagination.totalPages, 1) }}</span><div><button class="bo-page-button" :disabled="page <= 1" @click="changePage(page - 1)">Anterior</button><button class="bo-page-button" :disabled="page >= pagination.totalPages" @click="changePage(page + 1)">Siguiente</button></div></footer></section>
  <div v-if="showCardForm" class="bo-modal-backdrop" @click.self="showCardForm = false"><section class="bo-modal"><header><div><span class="bo-eyebrow">Registro lógico SIGA</span><h2>Nueva tarjeta</h2></div><button class="bo-close" type="button" @click="showCardForm = false">×</button></header><form class="bo-form" @submit.prevent="saveCard"><div class="bo-form-grid"><label>Código de tarjeta *<input v-model="cardForm.codigoTarjeta" maxlength="30" required /></label><label>Estado de tarjeta *<select v-model.number="cardForm.idEstadoTarjeta" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.estadosTarjeta" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.codigoTipoValor }} · {{ item.nombreTipoValor }}</option></select></label><label>Tipo de tarjeta<select v-model="cardForm.idTipoTarjeta"><option :value="null">Sin tipo</option><option v-for="item in options.tiposTarjeta" :key="item.idTipoTarjeta" :value="item.idTipoTarjeta">{{ item.nombreTipoTarjeta }}</option></select></label><label>Número de serie<input v-model="cardForm.numeroSerie" maxlength="100" /></label><label>Código externo<input v-model="cardForm.codigoExterno" maxlength="50" /></label><label>Fecha de alta *<input v-model="cardForm.fechaAlta" type="date" required /></label><label>Fecha de adquisición<input v-model="cardForm.fechaAdquisicion" type="date" /></label><label>Fecha de baja<input v-model="cardForm.fechaBaja" type="date" /></label><label class="bo-form-wide">Motivo de baja<textarea v-model="cardForm.motivoBaja" maxlength="500" rows="2" /></label><label class="bo-form-wide"><input v-model="cardForm.requiereRevision" type="checkbox" /> Requiere revisión</label><label class="bo-form-wide">Observación<textarea v-model="cardForm.observacionTarjeta" maxlength="1000" rows="2" /></label></div><footer class="bo-modal-actions"><button type="button" class="bo-btn" @click="showCardForm = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving || !cardFormValid">{{ saving ? "Guardando..." : "Registrar tarjeta" }}</button></footer></form></section></div>
  <div v-if="detail" class="bo-modal-backdrop" @click.self="detail = null"><section class="bo-modal"><header><div><span class="bo-eyebrow">Detalle de tarjeta</span><h2>{{ detail.codigoTarjeta }}</h2></div><button class="bo-close" type="button" @click="detail = null">×</button></header><div class="bo-form-grid"><p><strong>Estado:</strong> {{ detail.nombreEstadoTarjeta }}</p><p><strong>Registro:</strong> {{ new Date(detail.fechaRegistro).toLocaleString("es-HN") }}</p><p><strong>Serie:</strong> {{ detail.numeroSerie ?? "—" }}</p><p><strong>Asignación:</strong> {{ detail.idAsignacion ? detail.nombreEstadoAsignacion : "Disponible" }}</p></div><div v-if="detail.idAsignacion" class="bo-card"><h3>Asignación actual</h3><p>{{ detail.nombreBeneficiario }} · {{ detail.codigoSolicitud }}</p><p>{{ detail.perfilesAcceso ?? "Sin perfil" }} · {{ detail.fechaInicioVigencia?.slice(0, 10) }} — {{ detail.fechaFinVigencia?.slice(0, 10) ?? "Sin vencimiento" }}</p></div><div class="bo-actions"><button v-if="!detail.idAsignacion && can('TARJETAS_ASIGNAR')" class="bo-btn bo-btn-primary" @click="beginAction('assign')">Asignar</button><button v-if="detail.idAsignacion && can('TARJETAS_DESACTIVAR')" class="bo-action danger" @click="beginAction('return')">Devolver</button><button v-if="detail.idAsignacion && can('TARJETAS_RENOVAR')" class="bo-action" @click="beginAction('renew')">Renovar</button><button v-if="detail.idAsignacion && can('TARJETAS_ASIGNAR')" class="bo-action" @click="beginAction('replace')">Reemplazar</button><button class="bo-action" @click="action = 'history'">Consultar historial</button></div><div v-if="action && action !== 'history'" class="bo-card"><h3>{{ action === 'assign' ? 'Asignar tarjeta' : action === 'return' ? 'Devolver tarjeta' : action === 'replace' ? 'Reemplazar tarjeta' : 'Renovar asignación' }}</h3><div v-if="action === 'replace'" class="bo-form-grid"><label>Tarjeta nueva *<select v-model="assignmentForm.idTarjetaNueva"><option value="">Seleccione...</option><option v-for="item in available.filter(x => String(x.idTarjeta) !== String(detail?.idTarjeta))" :key="String(item.idTarjeta)" :value="String(item.idTarjeta)">{{ item.codigoTarjeta }}</option></select></label></div><div v-if="action === 'assign'" class="bo-form-grid"><label>Beneficiario *<select v-model="assignmentForm.idBeneficiario"><option value="">Seleccione...</option><option v-for="item in options.beneficiarios" :key="item.idBeneficiario" :value="String(item.idBeneficiario)">{{ item.nombreBeneficiario }}</option></select></label><label>Solicitud *<select v-model="assignmentForm.idSolicitud"><option value="">Seleccione...</option><option v-for="item in filteredRequests" :key="item.idSolicitud" :value="String(item.idSolicitud)">{{ item.codigoSolicitud }}</option></select></label><label>Perfil<select v-model="assignmentForm.idPerfilAcceso"><option value="">Sin perfil</option><option v-for="item in profiles" :key="item.idPerfilAcceso" :value="String(item.idPerfilAcceso)">{{ item.nombrePerfilAcceso }}</option></select></label></div><div class="bo-form-grid"><label>Estado de asignación *<select v-model.number="assignmentForm.idEstadoAsignacion"><option :value="0" disabled>Seleccione...</option><option v-for="item in options.estadosAsignacion" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Tipo de vigencia *<select v-if="action === 'assign'" v-model.number="assignmentForm.idTipoVigencia"><option :value="0" disabled>Seleccione...</option><option v-for="item in options.tiposVigencia" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Inicio *<input v-model="assignmentForm.fechaInicioVigencia" type="date" /></label><label>Fin<input v-model="assignmentForm.fechaFinVigencia" type="date" /></label></div><label v-if="action !== 'assign'" class="bo-form-wide">Motivo *<textarea v-model="assignmentForm.motivo" maxlength="1000" required rows="2" /></label><div class="bo-actions"><button class="bo-btn" type="button" @click="action = null">Cancelar</button><button class="bo-btn bo-btn-primary" @click="saveAction" :disabled="saving || !actionConfirmable">{{ saving ? 'Guardando...' : 'Confirmar' }}</button></div></div><div v-if="action === 'history'" class="bo-card"><h3>Historial de asignaciones</h3><p v-for="item in history" :key="String(item.idAsignacion)">{{ item.codigoTarjeta }} · {{ item.nombreBeneficiario }} · {{ item.fechaInicioVigencia?.slice(0, 10) }} — {{ item.fechaFinVigencia?.slice(0, 10) ?? 'Sin vencimiento' }} · {{ item.nombreEstadoAsignacion }}</p><p v-if="!history.length">Sin historial.</p></div></section></div>
</template>
